contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test entry; we take an amount to deposit
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward the deposit
        require(address(this).balance >= amount);

        // read observable before-values
        uint beforeCredit = c.credit(address(this));
        uint beforeBalance = address(c).balance;

        // perform the state-changing call: deposit with value 'amount'
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCredit = c.credit(address(this));
        uint afterBalance = address(c).balance;

        // General rule: deposit should not revert; if it didn't revert,
        // the contract's recorded credit for this caller increases by exactly amount
        // and the contract's Ether balance increases by exactly amount.
        assert((reverted == false) && (afterCredit == beforeCredit + amount) && (afterBalance == beforeBalance + amount));
    }

    // allow receiving Ether so the test can be funded externally
    receive() external payable {}
}

