        c.deposit{value: depositAmount}();

        // After deposit, the contract balance should have increased by depositAmount
        uint afterDepositContractBalance = address(c).balance;

        // Now attempt withdrawAll and catch whether it reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read on-chain observable values after the withdraw attempt
        uint finalContractBalance = address(c).balance;
        uint callerCredit;
        // credit is a public mapping; getter is credit(address) returns uint
        callerCredit = c.credit(address(this));

        // If withdrawAll did not revert, then the caller's credit must be zero and
        // the contract balance must have decreased by exactly depositAmount.
        // If it reverted, we don't require those to hold. This is a general property
