        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Record balances after first attempt
        uint balThisAfterFirst = address(this).balance;
        uint balCAfterFirst = address(c).balance;

        // Try second withdrawal and record whether it reverted and balances after
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint balThisAfterSecond = address(this).balance;
        uint balCAfterSecond = address(c).balance;

        // General rule: If the first withdraw did not revert, then the second withdraw cannot successfully transfer any additional Ether to this contract.
        // That is, either the second withdraw reverted, or it succeeded but did not increase this contract's balance.
        assert(firstReverted || secondReverted || balThisAfterSecond <= balThisAfterFirst);
    }

    // Allow receiving Ether when c sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a parameter amount to optionally seed some unrelated other address by depositing from this test
    // but the key input is a boolean indicator to decide whether to ensure the caller's credit is zero.
    function run(bool ensureZero, uint seedAmount) public payable {
        require(true);
        // ensure we have enough balance if we will deposit seedAmount
        if (seedAmount > 0) {
            require(address(this).balance >= seedAmount);
            // deposit from this test to c to create some other state; this increases credit[msg.sender]
            // but since msg.sender for these calls is this contract, it will set credit[this contract]
            // We'll later ensure credit for this contract is zero when ensureZero==true by withdrawing those funds first.
            c.deposit{value: seedAmount}();
        }

        // If the caller (this test contract) currently has positive credit and the caller wants to ensure zero,
        // withdraw those funds first so that the subsequent withdrawAll is invoked when credit==0.
        if (ensureZero) {
            // attempt to withdraw existing credit; ignore revert — but if it reverts, we still consider that withdrawAll when credit==0 condition may not hold,
            // however the property still must be general. We perform the try-catch to observe whether the attempted withdrawal reverted.
            bool firstReverted;
            try c.withdrawAll() {
                firstReverted = false;
            } catch {
                firstReverted = true;
            }
            // We do not assert on firstReverted; we just attempted to clear existing credit so that the next call more likely sees zero credit.
        }

        // Record balances before calling withdrawAll the test is about.
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Call withdrawAll and capture whether it reverts.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if the caller had zero recorded credit at the moment of the withdrawAll call,
        // then withdrawAll either reverts or causes no net change to c's balance and no net increase to this contract's balance.
        // We cannot directly read credit, so we infer zero-credit by the following observable implication:
        // If after a successful withdrawAll (reverted==false) the caller's balance did not increase, that indicates zero credit.
        // But we need a universal property: whenever credit is zero, then withdrawAll cannot non-revertingly transfer funds.
        // To express this without reading credit, we assert: Either the call reverted, or (afterC == beforeC && afterThis <= beforeThis).
        // This states that a successful call cannot increase this contract's balance nor decrease c's balance when caller had zero credit.
        // The formula is general over inputs and observable values.
        assert(reverted || (afterC == beforeC && afterThis <= beforeThis));
    }

    // Allow receiving Ether from C during withdrawAll
    receive() external payable { }
}

