    // attempt withdrawAll again and observe whether any Ether is transferred on the second attempt.
    function run(uint depositAmount, uint extra) public payable {
        require(address(this).balance >= depositAmount + extra);

        // Make an initial deposit of depositAmount into c
        c.deposit{value: depositAmount}();

        // Perform first withdrawAll and record if it reverted
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Record balances after first withdrawal attempt
