        uint selfBalAfterFirst = address(this).balance;

        // Attempt a second withdrawAll and capture whether it transfers any Ether to this contract.
        // We detect transfer by comparing balance before and after the second call.
        uint beforeSecond = address(this).balance;
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint afterSecond = address(this).balance;

        bool secondTransferred = (afterSecond > beforeSecond);

        // General rule: if the first withdrawAll succeeded (did not revert), then the second call
        // must not transfer any additional Ether to the caller (i.e., recorded credit has been cleared).
        // Conversely, if the first call reverted, we make no claim about the second transfer.
        assert(firstReverted || (!secondTransferred));
    }

    // Allow receiving Ether from C during .call in withdrawAll
